function studentActivitySql(): string {
 return "s.status='active' AND EXISTS (SELECT 1 FROM enrollments ae JOIN batches ab ON ab.id=ae.batch_id WHERE ae.student_id=s.id AND ae.status='active' AND ab.status='active' AND ae.start_date<=? AND ab.start_date<=? AND ab.end_date>=? AND (ae.end_date IS NULL OR ae.end_date>=?))";
}
function dashboardStudentActivity(): void {
 if(!can('students.view')||user()['teacher_id'])return;
 $today=date('Y-m-d');$args=[$today,$today,$today,$today];$predicate=studentActivitySql();
 foreach(['active_students'=>$predicate,'inactive_students'=>'NOT ('.$predicate.')'] as $label=>$where){
  $count=(int)scalar('SELECT COUNT(*) FROM students s WHERE '.$where,$args);panel($label);echo '<strong class="activity-count">'.$count.'</strong>';
  echo '<p class="muted">'.e(t('student_activity_hint')).'</p><details><summary>'.e(t('show_list')).' ('.$count.')</summary>';
  $rows=[];foreach(q('SELECT s.id,s.name,s.father_name,s.phone FROM students s WHERE '.$where.' ORDER BY s.name,s.id',$args) as $student)$rows[]=[ [sid((int)$student['id']),$student['name'],$student['father_name'],$student['phone']], [['profile','student',['id'=>$student['id']]],['new_enrollment','enrollments',['student_id'=>$student['id']]]] ];
  actionTable(['student_id','name','father_name','phone'],$rows);echo '</details>';endPanel();
 }
}
