 if(can('exams.view')){panel('upcoming_exams');$args=[date('Y-m-d'),date('Y-m-d',strtotime('+14 days'))];$sql='SELECT a.name,b.name batch,s.name subject,a.date FROM assessments a JOIN class_subjects cs ON cs.id=a.class_subject_id JOIN batches b ON b.id=cs.batch_id JOIN subjects s ON s.id=cs.subject_id WHERE a.date BETWEEN ? AND ?';if(user()['teacher_id']&&!can('*')){$sql.=' AND cs.teacher_id=?';$args[]=user()['teacher_id'];}table(['name','batches','subjects','date'],q($sql.' ORDER BY a.date',$args)->fetchAll());endPanel();}
