function modulePage(string $module): void {
 $mods=require __DIR__.'/modules.php';if(in_array($module,['rooms','programs','subjects','class_subjects'],true))echo '<div class="notice">'.e(t('help_'.$module)).'</div>';$m=$mods[$module];need($m['permission'].'.view');$rid=(int)($_GET['id']??0);$edit=isset($_GET['edit'])||isset($_GET['new']);
