 if($edit){need($m['permission'].($rid?'.update':'.create'));$record=$rid?one("SELECT * FROM `$module` WHERE id=?",[$rid]):[];if($rid&&!$record)throw new DomainException('not_found');if($module==='assessments'&&$rid)scopedClass((int)$record['class_subject_id']);panel($rid?'edit':'new_record');formStart('save_module',['module'=>$module,'id'=>$rid]);if(in_array($module,['students','teachers','employees'],true))photoField($module,$rid);if($module==='students'){
 workflowLinks('students',$rid?:null);
 foreach(['name','father_name','phone','registered_date','status'] as $key)field($key,$m['fields'][$key],$record[$key]??'');
 detailStart('additional_student_details',replaying());foreach($m['fields'] as $key=>$type)if(!str_starts_with($key,'tazkira_')&&!in_array($key,['name','father_name','phone','registered_date','status'],true))field($key,$type,$record[$key]??'');detailEnd();
 echo '<label class="wide checkbox-line"><input type="checkbox" name="duplicate_confirm"'.(formChecked('duplicate_confirm')?' checked':'').'> '.e(t('duplicate_confirm')).'</label>';
 }else foreach($m['fields'] as $key=>$type)if(!str_starts_with($key,'tazkira_'))field($key,$type,$record[$key]??'');
 if(in_array($module,['students','teachers','employees'],true))tazkiraFields($m['fields'],$record);
 formEnd('save',$module==='students'?['enroll'=>'save_enroll']:[]);endPanel();return;}
 if(can($m['permission'].'.create'))echo '<div class="toolbar no-print">'.linkTo('new_record',$module,['new'=>1]).'</div>';
 $search=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$where='';$args=[];
 if($search!==''){$clauses=['CAST(id AS CHAR) LIKE ?'];$args=['%'.$search.'%'];foreach($m['fields'] as $key=>$spec){$clauses[]="`$key` LIKE ?";$args[]='%'.$search.'%';}if(in_array($module,['students','teachers','employees'],true)){$clauses[]='public_code LIKE ?';$args[]='%'.$search.'%';}if($module==='students'){$clauses[]='id=?';$args[]=(int)preg_replace('/^KD-0*/i','',Domain::digits($search));}$where=' WHERE ('.implode(' OR ',$clauses).')';}
 $sort=(string)($_GET['sort']??'id');if(!in_array($sort,array_merge(['id'],array_keys($m['fields']),in_array($module,['students','teachers','employees'],true)?['public_code']:[]),true))$sort='id';$dir=($_GET['dir']??'desc')==='asc'?'asc':'desc';

 if(user()['teacher_id']&&!can('*')){if($module==='class_subjects'){$where.=($where?' AND':' WHERE').' teacher_id=?';$args[]=user()['teacher_id'];}elseif($module==='assessments'){$where.=($where?' AND':' WHERE').' class_subject_id IN (SELECT id FROM class_subjects WHERE teacher_id=?)';$args[]=user()['teacher_id'];}}
 panel($module);echo '<form class="searchbar no-print"><input type="hidden" name="r" value="'.e($module).'"><input name="q" value="'.e($search).'" placeholder="'.e(t('search')).'"><input type="hidden" name="sort" value="'.e($sort).'"><input type="hidden" name="dir" value="'.e($dir).'"><button>'.e(t('search')).'</button></form>';
 $count=(int)scalar("SELECT COUNT(*) FROM `$module`".$where,$args);$rows=q("SELECT * FROM `$module`".$where.' ORDER BY `'.$sort.'` '.$dir.', id '.$dir.' LIMIT 25 OFFSET '.(($page-1)*25),$args)->fetchAll();$fields=array_slice(array_keys($m['fields']),0,5);
 echo '<div class="table-wrap"><table data-server-sort><thead><tr><th>'.moduleSortLink($module,'id','#',$sort,$dir,$search).'</th>';foreach($fields as $f)echo '<th>'.moduleSortLink($module,$f,t($f==='capacity'?'seat_capacity':$f),$sort,$dir,$search).'</th>';echo '<th class="no-print">'.e(t('actions')).'</th></tr></thead><tbody>';
 $refs=[];foreach($fields as $f)if(str_starts_with($m['fields'][$f],'ref:'))foreach(options(substr($m['fields'][$f],4)) as $o)$refs[$f][$o['id']]=$o['name'];
 foreach($rows as $row){echo '<tr><td>'.(in_array($module,['students','teachers','employees'],true)?personPhoto($module,(int)$row['id']):'').'<bdi>'.e(in_array($module,['students','teachers','employees'],true)?personCode($module,(int)$row['id']):$row['id']).'</bdi></td>';foreach($fields as $f){$v=$refs[$f][$row[$f]??'']??$row[$f];if(str_contains($m['fields'][$f],'date'))$v=fdate($v);elseif(str_contains($m['fields'][$f],'choice:'))$v=t((string)$v);echo '<td>'.e($v).'</td>';}echo '<td class="no-print"><div class="actions">';if(can($m['permission'].'.update')&&$module!=='class_subjects')echo linkTo('edit',$module,['id'=>$row['id'],'edit'=>1]);if($module==='employees')echo linkTo('profile','employee',['id'=>$row['id']]);if($module==='students'){echo linkTo('profile','student',['id'=>$row['id']]);if(can('students.create')&&$row['status']==='active')echo linkTo('new_enrollment','enrollments',['student_id'=>$row['id'],'focus'=>'enroll']);if(can('finance.create'))echo linkTo('collect_payment','finance',['student_id'=>$row['id'],'focus'=>'receipt']);}if($module==='assessments')echo linkTo('marks','marks',['id'=>$row['id']]);echo '</div></td></tr>';}
 if(!$rows)echo '<tr><td colspan="8" class="empty">'.e(t('no_records')).'</td></tr>';echo '</tbody></table></div><div class="pagination no-print">';if($page>1)echo linkTo('previous',$module,['page'=>$page-1,'q'=>$search,'sort'=>$sort,'dir'=>$dir]);echo '<span>'.e($page).' / '.max(1,ceil($count/25)).'</span>';if($page*25<$count)echo linkTo('next',$module,['page'=>$page+1,'q'=>$search,'sort'=>$sort,'dir'=>$dir]);echo '</div>';endPanel();
}
