function studentStatement(int $id): void {
 panel('student_statement');$rows=[];$total=0;foreach(q('SELECT c.*,b.name FROM charges c JOIN enrollments en ON en.id=c.enrollment_id JOIN batches b ON b.id=en.batch_id WHERE en.student_id=? ORDER BY c.id',[$id]) as $c){$bal=Finance::chargeBalance((int)$c['id']);$total+=$bal;$rows[]=[$c['id'],$c['name'],$c['description'],fdate($c['due_date']),$c['amount'],Domain::money($bal)];}table(['id','batches','description','due_date','amount','balance'],$rows);$advance=0;$receipts=[];foreach(q('SELECT * FROM receipts WHERE student_id=? ORDER BY id',[$id]) as $r){$ad=Finance::advance((int)$r['id']);$advance+=$ad;$receipts[]=[$r['id'],fdate($r['date']),$r['amount'],Domain::money($ad)];}echo '<p>'.e(t('receivables')).': '.Domain::money($total).' AFN · '.e(t('advance')).': '.Domain::money($advance).' AFN</p>';table(['receipt_id','date','amount','advance'],$receipts);table(['charge_id','amount','reason'],q('SELECT cr.charge_id,cr.amount,cr.reason FROM credits cr JOIN charges c ON c.id=cr.charge_id JOIN enrollments en ON en.id=c.enrollment_id WHERE en.student_id=?',[$id])->fetchAll());table(['receipt_id','amount','reason'],q('SELECT rf.receipt_id,rf.amount,rf.reason FROM refunds rf JOIN receipts r ON r.id=rf.receipt_id WHERE r.student_id=?',[$id])->fetchAll());endPanel();
}
