function reportData(string $from,string $to): array {
 $received=Domain::cents(scalar('SELECT COALESCE(SUM(amount),0) FROM receipts WHERE date BETWEEN ? AND ?',[$from,$to]));$refunded=Domain::cents(scalar('SELECT COALESCE(SUM(amount),0) FROM refunds WHERE date BETWEEN ? AND ?',[$from,$to]));$income=Domain::cents(scalar("SELECT COALESCE(SUM(amount),0) FROM movements WHERE kind='income' AND date BETWEEN ? AND ?",[$from,$to]));$expenses=Domain::cents(scalar("SELECT COALESCE(SUM(amount),0) FROM movements WHERE kind='expense' AND date BETWEEN ? AND ?",[$from,$to]));$teacherPay=Domain::cents(scalar('SELECT COALESCE(SUM(amount),0) FROM payroll_payments WHERE date BETWEEN ? AND ?',[$from,$to]));$employeePay=Domain::cents(scalar('SELECT COALESCE(SUM(amount),0) FROM employee_payroll_payments WHERE date BETWEEN ? AND ?',[$from,$to]));$pay=$teacherPay+$employeePay;
 return [[t('collections'),Domain::money($received)],[t('refunds'),Domain::money($refunded)],[t('other_income'),Domain::money($income)],[t('expenses'),Domain::money($expenses)],[t('teacher_salary_paid'),Domain::money($teacherPay)],[t('employee_salary_paid'),Domain::money($employeePay)],[t('salary_paid'),Domain::money($pay)],[t('cash_surplus'),Domain::money($received-$refunded+$income-$expenses-$pay)]];
}
