 if($type==='certificate'){need('exams.view');if(user()['teacher_id']&&!can('*'))throw new DomainException('forbidden');$c=one('SELECT c.*,s.name,b.name batch FROM certificates c JOIN enrollments en ON en.id=c.enrollment_id JOIN students s ON s.id=en.student_id JOIN batches b ON b.id=en.batch_id WHERE c.id=?',[$id]);if(!$c)throw new DomainException('not_found');echo '<article class="certificate issued-certificate"><header><div class="issued-cert-brand">'.e(setting(lang()==='en'?'center_name_en':'center_name')).'</div><div class="issued-cert-subtitle">'.($c['kind']==='appreciation'?'CERTIFICATE OF APPRECIATION':'CERTIFICATE OF COMPLETION').'</div></header><h1>'.e(t($c['kind'])).'</h1><p class="cert-course">'.e(t('certificate_presented')).'</p><div class="cert-recipient">'.e($c['name']).'</div><p class="cert-course">'.e($c['batch']).'</p><p class="issued-cert-text">'.nl2br(e($c['wording'])).'</p><p class="issued-cert-text certificate-english" lang="en" dir="ltr">'.e($c['kind']==='appreciation'?'This certificate is proudly presented to '.$c['name'].' in recognition of dedication, effort and outstanding participation in '.$c['batch'].'.':'This is to certify that '.$c['name'].' has successfully completed the course '.$c['batch'].'.').'</p><div class="issued-cert-meta"><bdi>CT-'.str_pad((string)$id,8,'0',STR_PAD_LEFT).'</bdi> · <bdi>'.e(fdate($c['date'])).'</bdi></div>';if($c['revoked'])echo '<h2 class="certificate-revoked">'.e(t('revoked')).'</h2><p>'.e($c['reason']).'</p>';echo '<div class="signature"><span>'.e(t('signature')).'</span><span>'.e(t('stamp')).'</span></div></article>';echo '<div class="no-print">';formStart('certificate_print',['certificate_id'=>$id]);formEnd('record_print');echo '</div>';return;}
