 if($type==='id'){echo '<article class="id-card">'.personPhoto('students',$id).'<strong>'.e(setting(lang()==='en'?'center_name_en':'center_name')).'</strong><h2>'.e($s['name']).'</h2><p>'.e(t('father_name').': '.$s['father_name']).'<br><bdi>'.sid($id).'</bdi><br>'.e(setting('phone')).'</p></article>';}elseif(in_array($type,['registration','consent'],true)){panel($type==='registration'?'registration_form':'consent_form');echo personPhoto('students',$id);table(['field','value'],[[t('student_id'),sid($id)],[t('name'),$s['name']],[t('father_name'),$s['father_name']],[t('phone'),$s['phone']],[t('address'),$s['address']],[t('guardian'),$s['guardian']],[t('guardian_phone'),$s['guardian_phone']]]);if($type==='consent')echo '<p>'.e(t('consent_text')).'</p>';echo '<div class="signature">'.e(t('guardian_signature')).' __________________</div>';endPanel();}else throw new DomainException('not_found');
}
function usersPage(): void {
 need('users.manage');panel('users');echo '<p class="muted">'.e(t('employee_user_hint')).'</p>';
 $users=q('SELECT u.id,u.name,u.username,u.employee_id,r.name role,u.active,em.public_code FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN employees em ON em.id=u.employee_id ORDER BY u.id')->fetchAll();
 echo '<div class="table-wrap user-table"><table><thead><tr>';foreach(['id','photo','name','employee_id','username','role_id','active','actions'] as $key)echo '<th>'.e(t($key)).'</th>';echo '</tr></thead><tbody>';
 foreach($users as $v){echo '<tr><td>'.e($v['id']).'</td><td>'.personPhoto('users',(int)$v['id']).'</td><td>'.e($v['name']).'</td><td><bdi>'.e($v['public_code']?:t('primary_admin')).'</bdi></td><td>'.e($v['username']).'</td><td>'.e($v['role']).'</td><td>'.e(t($v['active']?'active':'archived')).'</td><td class="no-print">'.linkTo('edit','users',['id'=>$v['id']]).'</td></tr>';}echo '</tbody></table></div>';
 $uid=(int)($_GET['id']??0);$u=$uid?one('SELECT * FROM users WHERE id=?',[$uid]):[];if($uid&&!$u)throw new DomainException('not_found');echo '<div class="actions no-print">'.linkTo('new_record','users').'</div>';endPanel();
 panel($uid?'edit':'new_user');formStart('user',['id'=>$uid]);$primary=$u&&(int)$u['role_id']===1&&!$u['employee_id'];
 if($primary){echo '<p class="wide muted">'.e(t('primary_admin_exception')).'</p>';photoField('users',$uid);field('name','text',$u['name']);}
 else{echo '<div class="field"><label for="user-employee">'.e(t('employee_id')).' •</label><select id="user-employee" name="employee_id" required><option value="">—</option>';$selected=(int)formValue('employee_id',$u['employee_id']??0);
 foreach(q("SELECT em.id,em.name,em.job_title,em.public_code FROM employees em WHERE (em.status='active' AND NOT EXISTS(SELECT 1 FROM users u WHERE u.employee_id=em.id AND u.id<>?)) OR em.id=? ORDER BY em.name",[$uid,(int)($u['employee_id']??0)]) as $em)echo '<option value="'.e($em['id']).'"'.($selected===(int)$em['id']?' selected':'').'>'.e($em['name'].' / '.$em['job_title'].' / '.$em['public_code']).'</option>';echo '</select><small>'.e(t('employee_user_photo_hint')).'</small></div>';}
 field('username','text',$u['username']??'');echo '<div class="field"><label for="user-role">'.e(t('role_id')).' •</label><select id="user-role" name="role_id" required><option value="">—</option>';
 foreach(q('SELECT id,name FROM roles WHERE id<>4 ORDER BY id') as $role)echo '<option value="'.e($role['id']).'"'.((int)formValue('role_id',$u['role_id']??0)===(int)$role['id']?' selected':'').'>'.e($role['name']).'</option>';echo '</select></div>';
 field('password',$uid?'?password':'password');echo '<label><span><input type="checkbox" name="active"'.(formChecked('active',!$uid||(bool)$u['active'])?' checked':'').'> '.e(t('active')).'</span></label>';formEnd();endPanel();

 panel('roles');table(['id','name','permissions'],q('SELECT * FROM roles')->fetchAll());formStart('role');field('id','?int');field('name');foreach(Admin::permissions() as $p)echo '<label><span><input type="checkbox" name="permissions[]" value="'.e($p).'"'.(replaying()&&in_array($p,$_POST['permissions']??[],true)?' checked':'').'> '.e(t($p)).'</span></label>';formEnd();echo '<p class="muted">'.e(t('roles_hint')).'</p>';endPanel();
}
function settingsPage(): void {
 need('settings.manage');panel('settings');formStart('settings');foreach(['center_name','center_name_en','address','phone','footer','closure_days','low_attendance','backup_retention'] as $k)field($k,'?text',setting($k));formEnd();echo '<p class="muted">'.e(t('weekday_hint')).'</p>';endPanel();panel('new_account');echo '<p class="muted">'.e(t('opening_hint')).'</p>';formStart('account');field('name');field('opening_balance','money','0.00');formEnd();endPanel();
}
function backupPage(): void {
 need('backup.manage');panel('backup');echo '<p>'.e(t('backup_hint')).'</p>';formStart('backup');formEnd('create_backup');$files=array_reverse(glob(dirname(__DIR__).'/storage/backups/KD-*.zip'));echo '<ul>';foreach($files as $file)echo '<li>'.linkTo(basename($file),'backup_download',['file'=>basename($file)]).' · '.number_format(filesize($file)/1024,1).' KB</li>';echo '</ul><p>'.e(t('restore_hint')).'</p>';endPanel();
}
function auditPage(): void {
 need('audit.view');$page=max(1,(int)($_GET['page']??1));$search=trim((string)($_GET['q']??''));$columns=['id','actor_id','action','entity','record_id','details','created_at'];$sort=(string)($_GET['sort']??'id');if(!in_array($sort,$columns,true))$sort='id';$dir=($_GET['dir']??'desc')==='asc'?'asc':'desc';$args=[];$where='';
 if($search!==''){$where=' WHERE ('.implode(' OR ',array_map(fn($c)=>"`$c` LIKE ?",$columns)).')';$args=array_fill(0,count($columns),'%'.$search.'%');}
 panel('audit');echo '<form class="searchbar no-print"><input type="hidden" name="r" value="audit"><input name="q" value="'.e($search).'" aria-label="'.e(t('search')).'" placeholder="'.e(t('search')).'"><button>'.e(t('search')).'</button></form>';
 $count=(int)scalar('SELECT COUNT(*) FROM audit'.$where,$args);$rows=array_map(fn($row)=>[array_values($row),[]],q('SELECT '.implode(',',$columns).' FROM audit'.$where.' ORDER BY `'.$sort.'` '.$dir.' LIMIT 50 OFFSET '.(($page-1)*50),$args)->fetchAll());
 actionTable($columns,$rows,['module'=>'audit','sort'=>$sort,'dir'=>$dir,'q'=>$search]);echo '<div class="pagination no-print">';if($page>1)echo linkTo('previous','audit',['page'=>$page-1,'q'=>$search,'sort'=>$sort,'dir'=>$dir]);echo '<span>'.$page.' / '.max(1,ceil($count/50)).'</span>';if($page*50<$count)echo linkTo('next','audit',['page'=>$page+1,'q'=>$search,'sort'=>$sort,'dir'=>$dir]);echo '</div>';endPanel();
}
